[f1,r_load1,V_bias1,R_load1] = IEEE123function1plus_noise(vals);
[f2,r_load2,V_bias2,R_load2] = IEEE123function2plus_noise(vals);
[f3,r_load3,V_bias3,R_load3] = IEEE123function3plus_noise(vals);
[f4,r_load4,V_bias4,R_load4] = IEEE123function4plus_noise(vals);
[f5,r_load5,V_bias5,R_load5] = IEEE123function5plus_noise(vals);
[f6,r_load6,V_bias6,R_load6] = IEEE123function6plus_noise(vals);
[f7,r_load7,V_bias7,R_load7] = IEEE123function7plus_noise(vals);
